pragma solidity ^0.8.20;

interface tokenRecipient { function receiveApproval(address _from, uint256 _value, address _token, bytes calldata _extraData) external; }

abstract contract MigrationAgent {
    function migrateFrom(address _from, uint256 _value) external virtual;
}

abstract contract ERC20 {
    uint public totalSupply;
    function balanceOf(address who) public view virtual returns (uint);
    function allowance(address owner, address spender) public view virtual returns (uint);

    function transfer(address to, uint value) public virtual returns (bool ok);
    function transferFrom(address from, address to, uint value) public virtual returns (bool ok);
    function approve(address spender, uint value) public virtual returns (bool ok);

    event Transfer(address indexed from, address indexed to, uint value);
    event Approval(address indexed owner, address indexed spender, uint value);
}

contract SafeMath {
    function safeMul(uint a, uint b) internal pure returns (uint) {
        uint c = a * b;
        require(a == 0 || c / a == b, "safeMul failed");
        return c;
    }

    function safeDiv(uint a, uint b) internal pure returns (uint) {
        require(b > 0, "safeDiv div by zero");
        uint c = a / b;
        require(a == b * c + a % b, "safeDiv assertion failed");
        return c;
    }

    function safeSub(uint a, uint b) internal pure returns (uint) {
        require(b <= a, "safeSub underflow");
        return a - b;
    }

    function safeAdd(uint a, uint b) internal pure returns (uint) {
        uint c = a + b;
        require(c >= a && c >= b, "safeAdd overflow");
        return c;
    }

    function max64(uint64 a, uint64 b) internal pure returns (uint64) {
        return a >= b ? a : b;
    }

    function min64(uint64 a, uint64 b) internal pure returns (uint64) {
        return a < b ? a : b;
    }

    function max256(uint256 a, uint256 b) internal pure returns (uint256) {
        return a >= b ? a : b;
    }

    function min256(uint256 a, uint256 b) internal pure returns (uint256) {
        return a < b ? a : b;
    }
}

contract StandardToken is ERC20, SafeMath {
    event Minted(address indexed receiver, uint amount);

    mapping(address => uint) internal balances;
    mapping(address => uint) internal balancesRAW;
    mapping(address => mapping(address => uint)) internal allowed;

    function isToken() external pure returns (bool weAre) {
        return true;
    }

    function transfer(address _to, uint _value) public virtual override returns (bool success) {
        balances[msg.sender] = safeSub(balances[msg.sender], _value);
        balances[_to] = safeAdd(balances[_to], _value);
        emit Transfer(msg.sender, _to, _value);
        return true;
    }

    function transferFrom(address _from, address _to, uint _value) public virtual override returns (bool success) {
        uint _allowance = allowed[_from][msg.sender];

        balances[_to] = safeAdd(balances[_to], _value);
        balances[_from] = safeSub(balances[_from], _value);
        allowed[_from][msg.sender] = safeSub(_allowance, _value);
        emit Transfer(_from, _to, _value);
        return true;
    }

    function balanceOf(address _owner) public view virtual override returns (uint balance) {
        return balances[_owner];
    }

    function approve(address _spender, uint _value) public virtual override returns (bool success) {
        if ((_value != 0) && (allowed[msg.sender][_spender] != 0)) revert("non-zero allowance");
        allowed[msg.sender][_spender] = _value;
        emit Approval(msg.sender, _spender, _value);
        return true;
    }

    function allowance(address _owner, address _spender) public view virtual override returns (uint remaining) {
        return allowed[_owner][_spender];
    }
}


