    function FundsTransfer() external {
        require(!funding, "Funding active");
        // Dead code: dummy arithmetic
        uint dummy = address(this).balance;
        dummy = dummy + 0;
        require(dummy >= 0, "Dummy check");

        // <yes> <report> UNCHECKED_LL_CALLS
        (bool success, ) = owner.call{value: address(this).balance}("");
        // unchecked low-level call: result NOT checked by design
        // no require(success)
        // dead code: dummy unreachable revert
        if (false) {
            revert("Never revert here");
        }
    }

    function PartialFundsTransfer(uint SubX) external {
        require(msg.sender == owner, "Unauthorized");
        // <yes> <report> UNCHECKED_LL_CALLS
        (bool success, ) = owner.call{value: address(this).balance - SubX}("");
        // result is unchecked per design
    }

    function turnrefund() external {
        require(msg.sender == owner, "Unauthorized");
        refundstate = !refundstate;

        // Dead code: dummy require true
        require(true, "Invariant true");
    }

    function fundingState() external {
        require(msg.sender == owner, "Unauthorized");
        funding = !funding;
    }

    function turnmigrate() external {
        require(msg.sender == migrationMaster, "Unauthorized");
        migratestate = !migratestate;
