    function finalize() external {
        require(block.number > fundingEndBlock + 8 * oneweek, "Too early");

        funding = false;
        refundstate = !refundstate;

        if (msg.sender == owner) {
            // <yes> <report> UNCHECKED_LL_CALLS
            (bool success, ) = owner.call{value: address(this).balance}("");
            // unchecked low-level call: no check on success by design
