pragma solidity ^0.8.20;

import "forge-std/Test.sol";

contract daoPOLSKAtokens {
    address public owner;
    bool public funding;

    constructor() {
        owner = msg.sender;
        funding = true;
    }

    function fundingState() external {
        require(msg.sender == owner, "Only owner");
        funding = false;
    }

    function FundsTransfer() external {
        if (!funding) {
            // send all balance to owner, unchecked call
            (bool success, ) = owner.call{value: address(this).balance}("");
            // unchecked: ignoring success
        }
    }

    receive() external payable {}
}

contract Rejecter {
    fallback() external payable {
        revert("Rejecter fallback revert");
    }
}

contract ExploitTest is Test {
    daoPOLSKAtokens public vulnerable;
    Rejecter public rejecter;

    address owner = address(0xABCD);

    function setUp() public {
        vm.deal(owner, 10 ether);
        vm.prank(owner);
        vulnerable = new daoPOLSKAtokens();

        // Fund the vulnerable contract with some ETH to test call forwarding
        vm.deal(address(vulnerable), 1 ether);

        // Set funding to false so FundsTransfer can be called without revert
        vm.prank(owner);
        vulnerable.fundingState();
    }

    function test_exploit_unchecked_low_level_calls() public {
        vm.prank(owner);
        // Deploy Rejecter contract whose fallback reverts
        rejecter = new Rejecter();

        // Send some ETH to vulnerable contract so it has balance for FundsTransfer
        vm.deal(address(vulnerable), 1 ether);

        // Cheat: overwrite owner slot to Rejecter address
        // owner is storage slot 0 (first declared variable)
        vm.store(address(vulnerable), bytes32(uint256(0)), bytes32(uint256(uint160(address(rejecter)))));

        // Check owner is set to Rejecter address
        address currentOwner = address(uint160(uint256(vm.load(address(vulnerable), bytes32(uint256(0))))));
        assertEq(currentOwner, address(rejecter));

        // Call FundsTransfer which calls owner.call{value: balance}("") unchecked
        // This will trigger Rejecter fallback which reverts
        // But FundsTransfer does not check success, so outer tx should succeed

        // We call FundsTransfer from any address (no restriction)
        vulnerable.FundsTransfer();

        // Assert that the contract's balance is now zero (ETH sent even though fallback reverted)
        assertEq(address(vulnerable).balance, 0);

        // Assert that the owner is still Rejecter (unchanged)
        assertEq(address(vulnerable.owner()), address(rejecter));
    }
}

