            } else if (_step == 1) {
                // unchecked block to preserve vulnerability (underflow possible)
                unchecked {
                    balances[msg.sender] -= _value;
                }
                _step = 2;
            } else if (_step == 2) {
                balances[_to] += _value;
                _step = 3;
            } else if (_step == 3) {
                _continue = false;
            }
        }
        return true;
    }

    function balanceOf(address _owner) public view returns (uint balance) {
        return balances[_owner];
    }
}

