    function test_exploit_arithmetic() public {
        uint beforeCount = vuln.count();
        // input larger than count to trigger underflow in unchecked subtraction
        uint input = beforeCount + 1;

        // Call run with input that causes underflow: count - input under unchecked will wrap around
        uint res = vuln.run(input);

