pragma solidity ^0.8.33;

import "forge-std/Test.sol";

contract Vulnerable {
    mapping(address => uint256) public balances;

    // Deposit ETH to increase balance
    function deposit() external payable {
        balances[msg.sender] += msg.value;
    }

    // Vulnerable function: tries to send ETH to target using low-level call without checking success
    function sendEtherUnchecked(address payable target, uint256 amount) external {
        require(balances[msg.sender] >= amount, "Insufficient balance");
        balances[msg.sender] -= amount;

        // Unchecked call: does not revert or handle failure
        (bool success, ) = target.call{value: amount}("");
        // ignores success, so if call fails, funds are lost from sender's balance but not transferred
        // no revert or refund
    }
}

contract Rejecter {
    fallback() external payable {
        revert("Rejecter fallback revert");
    }
}

contract ExploitTest is Test {
    Vulnerable vulnerable;
    Rejecter rejecter;

    function setUp() public {
        vulnerable = new Vulnerable();
        rejecter = new Rejecter();

        // Fund attacker with 1 ether
        vm.deal(address(this), 1 ether);
        // Deposit 1 ether to vulnerable contract
        vulnerable.deposit{value: 1 ether}();
    }

    function test_exploit_unchecked_low_level_calls() public {
        uint256 beforeBalance = address(this).balance;
        uint256 attackerBalanceInContract = vulnerable.balances(address(this));
        assertEq(attackerBalanceInContract, 1 ether);

        // Attempt to send 1 ether to Rejecter, which will revert on fallback
        vulnerable.sendEtherUnchecked(payable(address(rejecter)), 1 ether);

        // The call inside sendEtherUnchecked reverts, but vulnerable contract ignores it,
        // so attacker balance in contract is decreased, but ether not sent out (lost in call)
        uint256 afterBalanceInContract = vulnerable.balances(address(this));
        assertEq(afterBalanceInContract, 0);

        // Attacker's external balance did NOT decrease (because call reverted and no ether sent)
        uint256 afterBalance = address(this).balance;
        assertEq(afterBalance, beforeBalance);

        // This shows funds were lost from internal accounting but not transferred, demonstrating unchecked low-level call vulnerability

        // Assert Rejecter contract code exists
        uint256 size;
        address rejecterAddr = address(rejecter);
        assembly {
            size := extcodesize(rejecterAddr)
        }
        assertGt(size, 0);

        // Assert Rejecter fallback reverts on direct call
        vm.expectRevert(bytes("Rejecter fallback revert"));
        (bool success, ) = address(rejecter).call("");
        assertTrue(!success);
    }
}

